def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); strata = sorted(set(feats.stratum))
    S = np.array([[s == t for t in strata[1:]] for s in feats.stratum], float).reshape(n, -1)
    base = np.column_stack([np.ones(n), S])
    R = np.corrcoef(X.T); R = np.nan_to_num(R)

    def ll(Z):
        A = np.column_stack([base, Z]) if Z is not None and Z.shape[1] else base
        b = np.zeros(A.shape[1])
        for _ in range(30):
            eta = np.clip(A @ b, -30, 30); m = 1 / (1 + np.exp(-eta)); w = m * (1 - m) + 1e-9
            H = A.T @ (A * w[:, None]) + 1e-6 * np.eye(A.shape[1])
            step = np.linalg.solve(H, A.T @ (y - m)); b += step
            if np.abs(step).max() < 1e-8: break
        eta = np.clip(A @ b, -30, 30)
        return float(np.sum(y * eta - np.logaddexp(0, eta)))

    def col(j):
        if isinstance(j, tuple): return X[:, j[0]] * X[:, j[1]]
        return X[:, j]

    def LL(js): return ll(np.column_stack([col(j) for j in js]) if js else None)

    def pv(lr, df=1): return stats.chi2.sf(max(lr, 0), df)
    sel = []; cur = LL([]); gates = [0.01 / p, 0.02 / p]
    while len(sel) < MAX_DRIVERS:
        cand = [j for j in range(p) if all(abs(R[j, k]) < 0.6 for k in sel)]
        if not cand: break
        lls = {j: LL(sel + [j]) for j in cand}
        j = max(lls, key=lls.get)
        if pv(2 * (lls[j] - cur)) > gates[min(len(sel), len(gates) - 1)]: break
        clus = [k for k in cand if abs(R[j, k]) >= 0.6 and lls[k] >= lls[j] - 2]
        if len(clus) > 1:
            def gsum(k):
                b0 = LL(sel + [k])
                return sum(LL(sel + [k, m]) - b0 for m in clus if m != k)
            j = min(clus, key=gsum)
        sel.append(j); cur = LL(sel)
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if pv(2 * (cur - LL(rest))) > 0.02 / p:
                sel = rest; cur = LL(sel); changed = True; break
    Xc = X - X.mean(0); m0 = 1 / (1 + np.exp(-0.0)); r = y - y.mean()
    pairs = [(a, b) for a in range(p) for b in range(a, p)]
    P = np.stack([X[:, a] * X[:, b] for a, b in pairs], 1); P = P - P.mean(0)
    sc = (r @ P) ** 2 / (np.sum(P ** 2, 0) * y.var() + 1e-12)
    prods = []; npair = len(pairs)
    for i in np.argsort(-sc)[:20]:
        a, b = pairs[i]
        mains = sorted(set(sel) | {a, b})
        base_ll = LL(mains + prods)
        lr = 2 * (LL(mains + prods + [(a, b)]) - base_ll)
        if pv(lr) < 0.01 / npair and len(prods) < 2:
            prods.append((a, b))
            for k in {a, b}:
                if k not in sel: sel.append(k)
    sel = sel[:MAX_DRIVERS]
    drivers = tuple(ids[j] for j in sel)
    return Design(drivers=drivers, columns=drivers,
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

